create or replace function tipshift_private.assert_pre_start_mutable() returns trigger language plpgsql set search_path=pg_catalog,tipshift_private as $$ declare target_turn uuid; current_state text; begin if tg_op='DELETE' then target_turn:=old.turn_ref; else target_turn:=new.turn_ref; end if; select state into current_state from tipshift_private.turns where turn_ref=target_turn; if tg_op='DELETE' and current_state='closed' then return old; end if; if current_state not in ('draft','claiming') then raise exception 'TipShift pre-start roster is locked.' using errcode='check_violation'; end if; if tg_op='DELETE' then return old; end if; return new; end; $$;
create or replace function tipshift_private.assert_valid_turn_transition() returns trigger language plpgsql set search_path=pg_catalog,tipshift_private as $$ declare group_total integer; group_count integer; unclaimed_count integer; empty_group_count integer; begin if tg_op='INSERT' then if new.state<>'draft' then raise exception 'A TipShift turn must be created as draft.' using errcode='check_violation'; end if; return new; end if; if new.state=old.state then return new; end if; if old.state='draft' and new.state='claiming' then select coalesce(sum(share_bps),0),count(*) into group_total,group_count from tipshift_private.turn_groups where turn_ref=new.turn_ref; if group_count=0 or group_total<>10000 then raise exception 'TipShift groups must sum exactly to 10,000 bps before claims open.' using errcode='check_violation'; end if; elsif old.state='claiming' and new.state='collecting' then select coalesce(sum(share_bps),0),count(*) into group_total,group_count from tipshift_private.turn_groups where turn_ref=new.turn_ref; select count(*) into unclaimed_count from tipshift_private.claim_capabilities where turn_ref=new.turn_ref and state<>'claimed'; select count(*) into empty_group_count from tipshift_private.turn_groups g where g.turn_ref=new.turn_ref and not exists(select 1 from tipshift_private.claim_capabilities c where c.turn_ref=g.turn_ref and c.group_ref=g.group_ref and c.state='claimed'); if group_count=0 or group_total<>10000 or unclaimed_count<>0 or empty_group_count<>0 then raise exception 'Every private recipient claim must be verified before collection starts.' using errcode='check_violation'; end if; elsif not ((old.state='draft' and new.state='closed') or (old.state='claiming' and new.state in ('draft','closed')) or (old.state='collecting' and new.state in ('disputed','settled','closed')) or (old.state='disputed' and new.state in ('collecting','settled','closed')) or (old.state='settled' and new.state='closed')) then raise exception 'Invalid TipShift turn transition: % -> %.',old.state,new.state using errcode='check_violation'; end if; return new; end; $$;
create trigger turns_valid_transition before insert or update on tipshift_private.turns for each row execute function tipshift_private.assert_valid_turn_transition(); create trigger turn_groups_pre_start_only before insert or update or delete on tipshift_private.turn_groups for each row execute function tipshift_private.assert_pre_start_mutable(); create trigger claim_capabilities_pre_start_only before insert or update or delete on tipshift_private.claim_capabilities for each row execute function tipshift_private.assert_pre_start_mutable();
alter table tipshift_private.turns add constraint turns_retention_cap check(retention_delete_after<=created_at+interval '31 days'); alter table tipshift_private.claim_capabilities add constraint claim_capabilities_retention_cap check((state='claimed' and retention_delete_after<=created_at+interval '31 days') or (state<>'claimed' and retention_delete_after<=expires_at+interval '24 hours'));
create or replace function tipshift_private.purge_expired_state(now_at timestamptz default timezone('utc',now())) returns table(purged_capabilities bigint,purged_turns bigint) language plpgsql set search_path=pg_catalog,tipshift_private as $$ begin with deleted as (delete from tipshift_private.claim_capabilities c using tipshift_private.turns t where c.turn_ref=t.turn_ref and t.state in ('draft','claiming') and c.retention_delete_after<=now_at returning 1) select count(*) into purged_capabilities from deleted; with deleted as (delete from tipshift_private.turns where closed_at is not null and retention_delete_after<=now_at returning 1) select count(*) into purged_turns from deleted; return next; end; $$;
revoke all on all functions in schema tipshift_private from public,anon,authenticated; alter default privileges in schema tipshift_private revoke all on functions from public,anon,authenticated;
